{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Scale history input embeddings by a fixed, bounded training-frequency feature so gated attention can distinguish common items from rare ones. Counts use only each category's training interactions. Persist the feature as a checkpoint buffer; the generated predictor imports the same model class and restores it automatically. Candidate embeddings, learned parameters, HSTU topology, readout, loss and optimizer remain unchanged.",
      "edits": [
        {
          "find": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        self.pos_emb = nn.Embedding(maxlen + 1, hidden_units, padding_idx=0)",
          "replace": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        self.register_buffer(\"input_frequency_scale\", torch.ones(itemnum + 1))\n        self.input_frequency_scale[0] = 0.0\n        self.pos_emb = nn.Embedding(maxlen + 1, hidden_units, padding_idx=0)"
        },
        {
          "find": "        seq_emb = self.item_emb(seq) * math.sqrt(self.hidden_units)",
          "replace": "        seq_emb = self.item_emb(seq) * math.sqrt(self.hidden_units)\n        seq_emb = seq_emb * self.input_frequency_scale[seq].unsqueeze(-1)"
        },
        {
          "find": "    optimizer = torch.optim.AdamW(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    training_counts = np.zeros(itemnum + 1, dtype=np.int64)\n    for history in user_train.values():\n        np.add.at(training_counts, np.asarray(history, dtype=np.int64), 1)\n    training_counts[0] = 0\n    log_counts = np.log1p(training_counts.astype(np.float64))\n    frequency_scale = 0.75 + 0.5 * log_counts / max(float(log_counts.max()), 1.0)\n    frequency_scale[0] = 0.0\n    with torch.no_grad():\n        model.input_frequency_scale.copy_(torch.as_tensor(\n            frequency_scale, dtype=model.input_frequency_scale.dtype, device=device\n        ))\n    optimizer = torch.optim.AdamW(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
        }
      ]
    }
  ],
  "change_summary": "Add a checkpointed training-frequency input scale for all four category models, with automatic predictor restoration and no changes to scoring, model parameters or training settings."
}
